def rd(p): return open(p, encoding='utf-8').read()
def R(pat, text, name):
    g = re.search(pat, text, re.M); assert g, (name, pat); return g.group(1)
ck = rd(f'{SP}/ch29_rows_check.out'); assert 'THE RUN-2 IMPORT CHECK GREEN' in ck
NO = int(R(r'^ONKELOS TYPED: (\d+) \|', ck, 'onkelos')); BYC = R(r'\| by chapter: (\{[^}]*\}) \|', ck, 'by chapter'); VO = R(r"^ONKELOS TYPED.*\| verdicts: Counter\((\{[^}]*\})\)$", ck, 'onkelos verdicts')
NS = int(R(r'^THE SPINE TYPED: (\d+) \|', ck, 'spine')); VS = R(r"^THE SPINE TYPED.*\| verdicts: Counter\((\{[^}]*\})\)$", ck, 'spine verdicts')
NX = int(R(r'^THE OUTSIDE ROWS TYPED: (\d+) \|', ck, 'outside')); VX = R(r"^THE OUTSIDE ROWS TYPED.*\| verdicts: Counter\((\{[^}]*\})\)$", ck, 'outside verdicts'); NRR = int(R(r'the REREAD marks: (\d+) \|', ck, 'reread'))
FR = R(r'^  the fresh rows: (\[.*?\]) \|', ck, 'fresh'); PB = int(R(r'bytes of prose: (\d+)', ck, 'prose')); FAILS = R(r"the cuts' misses \(FAIL\): (\[.*?\])$", ck, 'fails'); assert FAILS == '[]', FAILS
lg = rd(f'{SP}/ch29_ledger.out'); LB = int(R(r'THE LEDGER WRITTEN: .* — ([\d,]+) bytes;', lg, 'ledger bytes').replace(',', '')); NSRC = int(R(r'; sources (\d+) \(', lg, 'sources')); LK = R(r'the kin (\d+ ledgers / \d+ rows) computed', lg, 'kin'); LLINT = R(r'lint: gloss_lint: (\d+) flag', lg, 'lint'); assert LLINT == '0', LLINT
mf = rd(f'{SP}/ch29_manifest.out'); NCL = int(R(r'^claims (\d+) \|', mf, 'claims')); assert 'used by exactly one claim: True' in mf; NMF = len(re.findall(r'^wrote ', mf, re.M))
sd_ = rd(f'{SP}/ch29_seat_derive.out'); SEATS = R(r'three units, ([\d +]+) seats', sd_, 'seats')
ct = rd(f'{ROOT}/logic/corpus/CORPUS_TRUTH.py'); U0 = int(R(r'assert len\(W\["units"\]\) == (\d+)', ct, 'U0')); S0 = int(R(r'assert len\(W\["standing"\]\) == (\d+)', ct, 'S0')); assert (U0, S0) in ((244, 2329), (247, 2344)), (U0, S0)   # before the chain's fold step, or the tripwire already set to the prediction by it
NT = len([l for l in rd(f'{SP}/ch29_timing.tsv').split('\n') if l.startswith(('0', '1', '2'))])
LAUNCHED = os.path.exists(f'{SP}/ch29_gates.log') and not os.path.exists(f'{SP}/ch29_gates.DONE')
print('THE PRINTS: the check — Onkelos %d %s %s, spine %d %s, outside %d %s (reread %d, fresh %s), %d bytes, FAIL %s; the ledger %d bytes, %d sources, the kin %s, lint %s; the manifests %d files / %d claims; the seats %s; the tripwire %d/%d; %d timed steps; the chain launched: %s' % (NO, BYC, VO, NS, VS, NX, VX, NRR, FR, PB, FAILS, LB, NSRC, LK, LLINT, NMF, NCL, SEATS, U0, S0, NT, LAUNCHED))
assert LAUNCHED or CHECK, 'the chain is not running — launch it before the point is written'
# ---- #228 ----
sd = rd(SD); assert '\n#228 ' not in sd and '\n#227 (' in sd
P228 = ('\n\n#228 (2026-09-27, THE DEUTERONOMY WALK sitting 19 — CHAPTERS 29-31\'s READING IN THE LEAN FORM, RUN 2 of two; on the owner\'s "Reread and go" after the compaction at #227 — no commit word said, the tree UNCOMMITTED since 68191ea with sitting 18b riding and 19 on it; A CLEAN COMPACTION POINT AT RUN 2\'s END WITH THE GATES CHAIN RUNNING: THE REREADS done (the recovery page, the map\'s sitting-19 section, MEMORY.md, #227 and its READY note; THE_STEPS\' compiler block, Step 2 whole and Step 5\'s head before the ledger); THE ROWS ALL READ WHOLE AND TYPED IN THIS RUN — ONKELOS 29, 30 AND 31 (%d verses read in four slices with the parse lines dropped, typed in four files %s, the verdicts %s), THE SPINE 304-305 (%d rows read whole from the split\'s two files — 305\'s six long rows whole — the verdicts %s), THE NINETEEN OUTSIDE ROWS (%d read whole in two slices, the verdicts %s, %d REREAD WHOLE as computed, the fresh %s); THE IMPORT CHECK GREEN in one run (%d bytes of prose; the cuts\' misses %s; every key inside SPAN, READ_ROWS and OUTSIDE; no spine row read before); THE LEDGER logic/oral_triage/deu_29_31_nitzavim_vayelech_2026-09-27.md (%s bytes; %d sources = 78 Onkelos + 8 spine + 19 outside, none excluded; coverage COMPUTED; the kin %s; the citation counts parsed from the dumps\' prints — the unions 4, 3, 17; lint %s — three flags on the first write, a Hebrew marker in parentheses without the cut form (157:10\'s Mishnah Sotah 7:8), the marker cut by SP_ and glossed, the ledger rewritten by its own writer under DEU_REWRITE=1); THE MANIFESTS (%d files, %d claims DV29-01..05, DV30-01..04, DV31-01..06 — every cite index name used by exactly one claim; the middah codes checked in MIDDOT.md and typed only where a row argues by them: I2 at 109:2, 111:1 and 302:1 (the end analogy from 31:10), I13 at 334:1 (went against came), E26 at 53:1 and 305:2 (the parables), I1 in the ink\'s own 31:27; "no middah code typed" said elsewhere; 302:1 seated by 31:10 by a named override — the Hebrew marker\'s 31:7 a misprint for the row\'s own word; every check piece cut from the store\'s own bytes); THE DEPARTURES FROM THE DESIGN BY COMPUTATION: the ranges contiguous — DV31-03 is 31:14-15 and 31:23 folds into DV31-05 (31:19-23); 43:7 and 318:1 (on 31:20) in DV31-05 not DV31-04; 302:1 and 357:28 in DV31-02; 334:1 (on 31:1) in DV31-01; 306:15 in DV30-04 (30:19 its first cite); THREE HEBREW MARKERS MISPRINTED IN THE EXPORT (1:1 marks 31:22 for 31:9\'s words, 302:1 marks 31:7 for 31:10\'s, 357:28 marks 31:24 for 31:9\'s — the English true at each; seated by the words); TWO PREFIXED BLANK GLOSSES found at the read (31:18, 31:23 ve-anokhi "and-?") beyond the ink\'s eight; THE SEAT derived (seat_ch29.py from the forms\' seat_ch26.py — %s seats at the claims\' first verses); THE CHAIN SCRIPTS derived (ch29_chain.sh, ch29_fold.sh with the tripwire 244 -> 247 and 2329 -> 2344, ch29_gates.sh, ch29_gates_wrap.sh, ch29_vc.sh); THE GATES CHAIN LAUNCHED at RUN 2\'s end (ch29_gates_wrap.sh — seat x3, verify_text x3, the ritual x3, the fold, build_world, the journal gate, the register gate --strict, large_letter, the home gate; the DONE file ch29_gates.DONE; its SUMMARY ch29_gates_SUMMARY.txt read ONCE at the tail, never polled); the fold\'s tripwire at %d/%d when this point was written; %d timed steps; the tree UNCOMMITTED. NEXT: THE TAIL after the compaction — read the SUMMARY once (if red: the demands filed from the prints, the pass resumed from the failed step — a pass after any source change starts at the seat); verify_claims (ch29_vc.sh); the display patch (the eight bare "?" glosses of the pronoun I at 29:5, 29:13, 30:2, 30:8, 30:11, 30:16, 31:2, 31:27 and the two prefixed at 31:18, 31:23 probed first — ch29_patch_probe.py from the forms\' ch26_patch_probe.py, then the overrides; "duplicate" for the witness verb, "try" for choose, "goad" for learn among the candidates); the labels census --strict; THE FOUR RECORDS (the map\'s AS BUILT — LEAN with the departures, the lessons and the timing table; the state doc\'s NOTE under this checkpoint; the recovery page; the memory) + COMPILE_DEBT\'s lean box line (10) replacing the anchor " 19 (the reading of 29-31): next." and adding " 19b (the compile of 29-31): next."; the commit message write_ch29_commit_msg.py folding commit_msg_ch26b.txt (18b + 19; the trailers once); the forms; then THE COMMIT ON HIS WORD ONLY ("Commit" = no push; "commit push" = both). POST-COMPACTION REREADS: the recovery page, the map\'s newest section ("Sitting 19 — CHAPTERS 29-31 … LEAN"), MEMORY.md; then this checkpoint.'
        % (NO, BYC, VO, NS, VS, NX, VX, NRR, FR, PB, FAILS, f'{LB:,}', NSRC, LK, LLINT, NMF, NCL, SEATS, U0, S0, NT))
# ---- the recovery page (section 2 rewritten whole, under its cap) ----
